css:
.pf {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 11px;
    color: #333;
    line-height: 1.4;
}
.pf * { box-sizing: border-box; }

/* Tables */
.pf table { width: 100%; border-collapse: collapse; }
.pf th, .pf td {
    border: 1px solid #aaa;
    padding: 6px 8px;
    vertical-align: top;
    overflow-wrap: break-word;
    word-break: break-word;
}
.pf thead { display: table-header-group; }
.pf tbody { display: table-row-group; }
.pf thead th { background: #f0f0f0; font-weight: bold; }
.pf tr { page-break-inside: auto; break-inside: auto; }
.pf td { page-break-inside: auto; break-inside: auto; }

/* Rich-text cell — collapses phantom <p><br></p> that editors emit. */
.pf .desc p, .pf .desc div, .pf .desc span {
    margin: 0 !important;
    padding: 0 !important;
    display: inline;
}

/* Typography helpers */
.pf .title {
    text-align: center;
    font-size: 18px;
    font-weight: bold;
    letter-spacing: 2px;
    margin: 10px 0 14px;
    color: #2c3e50;
}
.pf .section {
    font-size: 12px;
    font-weight: bold;
    color: #2c3e50;
    border-bottom: 1px solid #2c3e50;
    padding-bottom: 2px;
    margin: 14px 0 4px;
}
.pf .r { text-align: right; }
.pf .c { text-align: center; }
.pf .b { font-weight: bold; }
.pf .muted { color: #777; font-size: 10px; }

/* Totals block — stays together on one page */
.pf .totals {
    width: 45%;
    margin-left: auto;
    page-break-inside: avoid;
    break-inside: avoid;
}
.pf .totals td { border: none; padding: 3px 6px; }
.pf .totals .grand td {
    border-top: 2px solid #2c3e50;
    font-weight: bold;
    font-size: 13px;
    padding-top: 4px;
}
